// Satış bloklarının ortak yazımı ve kuruş hesabı. Para TRY'dir; sayılar ABACUS'tandır (Intl, toFixed yok).
import { math, money } from "@snn/abacus-core";
import { formatMoney, formatNumber } from "./chart-format";

/** Ana birimdeki tutarı kuruş tamsayısına çevirir (12.5 → 1250). Geçersizse 0. */
export const toMinor = (major: number): number => money.toMinor(major) ?? 0;
/** Kuruş tamsayısını ana birime çevirir (1250 → 12.5), yalnız gösterim için. */
export const toMajor = (minor: number): number => math.div(minor, 100) ?? 0;

/** Ürün fiyatı: kuruşu yoksa "₺1.250", varsa "₺1.250,50". */
export function priceText(major: number): string {
  return formatMoney(major, toMinor(major) % 100 === 0 ? 0 : 2);
}

/** Tutar her zaman iki ondalıkla ("₺4.801,80"); toplam satırlarında hizalı durur. */
export const exactText = (minor: number): string => formatMoney(toMajor(minor), 2);

/** İşaretli tutar: "+₺12,00", "-₺12,00". Sıfır işaretsiz yazılır. */
export function signedMinorText(minor: number): string {
  return minor > 0 ? `+${exactText(minor)}` : exactText(minor);
}

/** Adet ya da sayaç: "1.234". */
export const countText = (count: number): string => formatNumber(count, 0);

/** Tek ondalıklı ortalama: 4.6 → "4,6". */
export const averageText = (value: number): string => money.fmtDecimalGrouped(math.round(value, 1), 1);

/** Adet × birim fiyat, kuruş tamsayısıyla. */
export const lineMinor = (unitMinor: number, quantity: number): number => math.mul(unitMinor, Math.max(0, quantity));

/** Yüzde yazımı: 20 → "%20". */
export const percentText = (percent: number, digits = 0): string => money.percent(percent, digits);

/** Sayıyı aralığa sıkıştırır. */
export const clampInt = (value: number, low: number, high: number): number => Math.min(high, Math.max(low, Math.round(value)));

"use client";

import { useCallback, useRef, useState, type CSSProperties, type KeyboardEvent, type ReactNode } from "react";
import { countText } from "./shop-format";
import styles from "./shop-parts.module.css";

/** Görsel yer tutucu: düz renk yüzey ve küçük bir çizim. Gerçek fotoğraf yerine geçer; `label` ekran okuyucu için alt metindir. */
export function Placeholder({ tone = 0, label, ratio = "4 / 5", className, children }: { tone?: number; label: string; ratio?: string; className?: string; children?: ReactNode }) {
  return <div className={[styles.placeholder, className].filter(Boolean).join(" ")} data-tone={Math.abs(tone) % 6} role="img" aria-label={label} style={{ aspectRatio: ratio }}>
    {children ?? <svg viewBox="0 0 48 48" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><rect x="6" y="9" width="36" height="30" rx="4" /><circle cx="17" cy="20" r="3.5" /><path d="M6 34l10-9 8 7 6-5 12 9" /></svg>}
  </div>;
}

export interface SwatchOption { value: string; label: string; /** Örneğin rengi (CSS rengi); uygulamanın verisidir. */ color: string; disabled?: boolean }

/**
 * Renk örnekleri. `mode="multi"`: her örnek açma-kapama düğmesidir (`aria-pressed`, süzgeç için).
 * `mode="single"`: radyo grubu, gezen odak ve ok tuşları (ürün sayfası seçimi için).
 */
export function SwatchGroup({ label, options, value, onToggle, mode = "multi" }: { label: string; options: SwatchOption[]; value: string[]; onToggle: (value: string) => void; mode?: "multi" | "single" }) {
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const checkedAt = Math.max(0, options.findIndex(option => value.includes(option.value)));
  const move = (event: KeyboardEvent, at: number) => {
    if (mode !== "single") return;
    const step = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 0;
    if (!step) return;
    event.preventDefault();
    const next = (at + step + options.length) % options.length;
    refs.current[next]?.focus();
    onToggle(options[next]!.value);
  };
  return <div className={styles.swatches} role={mode === "single" ? "radiogroup" : "group"} aria-label={label}>
    {options.map((option, at) => {
      const on = value.includes(option.value);
      const common = { type: "button" as const, className: styles.swatch, style: { "--swatch": option.color } as CSSProperties, disabled: option.disabled, "aria-label": option.label, title: option.label, onClick: () => onToggle(option.value), onKeyDown: (event: KeyboardEvent) => move(event, at), ref: (node: HTMLButtonElement | null) => { refs.current[at] = node; } };
      return mode === "single"
        ? <button key={option.value} {...common} role="radio" aria-checked={on} tabIndex={at === checkedAt ? 0 : -1} />
        : <button key={option.value} {...common} aria-pressed={on} />;
    })}
  </div>;
}

/** Üst sınırı olan adet düzenleyici. `removeAtMin`: en küçük değerde eksi düğmesi "Kaldır" olur ve `onRemove` çağrılır. */
export function NumberStepper({ label, value, min = 1, max = 99, onChange, onRemove, removeLabel = "Kaldır" }: { label: string; value: number; min?: number; max?: number; onChange: (value: number) => void; onRemove?: () => void; removeLabel?: string }) {
  const atMin = value <= min;
  const minusLabel = atMin && onRemove ? `${label}: ${removeLabel}` : `${label}: azalt`;
  return <div className={styles.stepper} role="group" aria-label={label}>
    <button type="button" aria-label={minusLabel} disabled={atMin && !onRemove} onClick={() => atMin ? onRemove?.() : onChange(value - 1)}>{atMin && onRemove ? "✕" : "−"}</button>
    <output aria-live="off">{countText(value)}</output>
    <button type="button" aria-label={`${label}: artır`} disabled={value >= max} onClick={() => onChange(value + 1)}>+</button>
  </div>;
}

/** Kibar canlı bölge: `announce` metni yazar. Aynı metin art arda gelirse ekran okuyucu yine okusun diye sonuna görünmez ayraç eklenir. */
export function useAnnouncer(): [ReactNode, (message: string) => void] {
  const [message, setMessage] = useState("");
  const toggle = useRef(false);
  const announce = useCallback((next: string) => { toggle.current = !toggle.current; setMessage(toggle.current ? next : `${next} `); }, []);
  return [<div key="live" className={styles.srOnly} role="status" aria-live="polite" aria-atomic="true">{message}</div>, announce];
}

export const srOnly = styles.srOnly;

.placeholder { position: relative; display: grid; place-items: center; width: 100%; overflow: hidden; background: var(--ph-bg, var(--surface-muted)); color: var(--ph-fg, var(--text-muted)); }
.placeholder svg { width: 38%; height: auto; max-height: 60%; opacity: .75; }
.placeholder[data-tone="0"] { --ph-bg: color-mix(in oklch, var(--accent) 16%, var(--surface)); --ph-fg: var(--accent-strong); }
.placeholder[data-tone="1"] { --ph-bg: var(--neutral-3); --ph-fg: var(--neutral-7); }
.placeholder[data-tone="2"] { --ph-bg: color-mix(in oklch, var(--success) 18%, var(--surface)); --ph-fg: var(--success); }
.placeholder[data-tone="3"] { --ph-bg: color-mix(in oklch, var(--accent) 32%, var(--surface)); --ph-fg: var(--accent-strong); }
.placeholder[data-tone="4"] { --ph-bg: var(--neutral-5); --ph-fg: var(--neutral-9); }
.placeholder[data-tone="5"] { --ph-bg: color-mix(in oklch, var(--accent) 8%, var(--neutral-2)); --ph-fg: var(--neutral-8); }

.swatches { display: flex; flex-wrap: wrap; gap: var(--space-2); margin: 0; padding: 0; border: 0; }
.swatch { position: relative; width: 1.75rem; height: 1.75rem; padding: 0; border: 1px solid var(--border-strong); border-radius: var(--radius-pill); background: var(--swatch, var(--neutral-4)); cursor: pointer; }
.swatch::after { content: ""; position: absolute; inset: -4px; border: 2px solid transparent; border-radius: inherit; transition: border-color var(--duration-fast, .16s); }
.swatch[aria-pressed="true"]::after, .swatch[aria-checked="true"]::after { border-color: var(--foreground); }
.swatch:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 5px; }
.swatch:disabled { cursor: not-allowed; opacity: .4; }
.swatchDot { display: inline-block; width: .6rem; height: .6rem; border: 1px solid var(--border-strong); border-radius: var(--radius-pill); background: var(--swatch, var(--neutral-4)); }

.stepper { display: inline-flex; align-items: center; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); }
.stepper button { width: 2rem; height: 2rem; border: 0; border-radius: var(--radius-control); background: transparent; color: var(--foreground); font-size: var(--text-base); cursor: pointer; }
.stepper button:hover:not(:disabled) { background: var(--surface-muted); }
.stepper button:disabled { color: var(--text-muted); cursor: not-allowed; }
.stepper button:focus-visible { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, var(--accent)); outline-offset: 1px; }
.stepper output { min-width: 2rem; text-align: center; font-size: var(--text-sm); font-variant-numeric: tabular-nums; }

.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
